  "En el móvil, escanea el QR (o abre esta dirección e introduce el código). Podrás ver las notas, pasar diapositivas y usar el panel táctil: puntero, foco, lupa y tocar la diapositiva.": "No móbil, escanea o QR (ou abre este enderezo e introduce o código). Poderás ver as notas, pasar diapositivas e usar o panel táctil: punteiro, foco, lupa e tocar a diapositiva.",
