  "Toca para pulsar; arrastra para mover; desliza con dos dedos para desplazar; pellizca para ampliar y toca dos veces para volver. Las webs de otros sitios no se pueden tocar desde aquí.": "Toca para premer; arrastra para mover; esvara con dous dedos para desprazar; belisca para ampliar e toca dúas veces para volver. As webs doutros sitios non se poden tocar desde aquí.",
