  "Las demás no le llegan: ni su contenido ni su título. Puedes ampliar o reducir la elección cuando quieras; las diapositivas nuevas no se añaden solas.": "As demais non lle chegan: nin o seu contido nin o seu título. Podes ampliar ou reducir a escolla cando queiras; as diapositivas novas non se engaden soas.",
  "Te ha compartido solo algunas diapositivas: puede añadir más cuando quiera.": "Compartiu contigo só algunhas diapositivas: pode engadir máis cando queira.",
  "Cada tramo puede ir a su velocidad: pasa deprisa (2×, 4×…) por lo que hay entre las partes que interesan y vuelve a la normal en ellas. «Igual» usa la velocidad de arriba.": "Cada tramo pode ir á súa velocidade: pasa axiña (2×, 4×…) polo que hai entre as partes que interesan e volve á normal nelas. «Igual» usa a velocidade de arriba.",
