  "Paquete SCORM para Moodle, Canvas u otra plataforma: cada alumno la recorre a su ritmo, responde sus cuestionarios y actividades, y la plataforma recibe su nota (la media, sobre 100) y dónde se quedó. Nota para aprobar (de 0 a 100):": "Paquete SCORM para Moodle, Canvas ou outra plataforma: cada alumno percórrea ao seu ritmo, responde os cuestionarios e actividades, e a plataforma recibe a súa nota (a media, sobre 100) e onde quedou. Nota para aprobar (de 0 a 100):",
  "Paquete SCORM descargado: súbelo a tu plataforma como «Paquete SCORM».": "Paquete SCORM descargado: súbeo á túa plataforma como «Paquete SCORM».",
