  "Cada persona escribe una respuesta corta; salen en un muro, las más recientes primero.": "Cada persoa escribe unha resposta curta; saen nun muro, as máis recentes primeiro.",
  "Cada persona da un número con un deslizador; se ven la media, la mediana y cómo se reparten, y la respuesta si la pones.": "Cada persoa dá un número cun control deslizante; vense a media, a mediana e como se reparten, e a resposta se a pos.",
