  "Para Moodle, Canvas u otra plataforma: cada alumno la recorre a su ritmo, responde sus cuestionarios y actividades, y la plataforma recibe su nota (la media, sobre 100) y dónde se quedó.": "Para Moodle, Canvas ou outra plataforma: cada alumno percórrea ao seu ritmo, responde os cuestionarios e actividades, e a plataforma recibe a súa nota (a media, sobre 100) e onde quedou.",
  "Copia fija": "Copia fixa",
  "la presentación va dentro del paquete y funciona sin internet. Si la cambias, hay que exportarla y subirla otra vez.": "a presentación vai dentro do paquete e funciona sen internet. Se a cambias, hai que exportala e subila outra vez.",
  "Dinámica": "Dinámica",
  "el paquete abre la presentación desde tu nube de Revela: lo que corrijas lo verán tus alumnos la próxima vez, sin volver a subir nada. Necesita internet.": "o paquete abre a presentación desde a túa nube de Revela: o que corrixas verano os teus alumnos a próxima vez, sen volver subir nada. Precisa internet.",
  "Para la dinámica, guárdala primero en tu nube de Revela.": "Para a dinámica, gárdaa primeiro na túa nube de Revela.",
  "Para la dinámica tiene que exportarla quien puede compartirla.": "A dinámica ten que exportala quen pode compartila.",
  "Para la dinámica se compartirá por enlace, solo para ver (sin el editor). Las diapositivas y permisos que elijas al compartir se respetan.": "Para a dinámica compartirase por ligazón, só para ver (sen o editor). Respéctanse as diapositivas e permisos que escollas ao compartir.",
  "Nota para aprobar (de 0 a 100)": "Nota para aprobar (de 0 a 100)",
  "Paquete SCORM dinámico descargado: súbelo a tu plataforma como «Paquete SCORM». Mostrará siempre la última versión de tu nube.": "Paquete SCORM dinámico descargado: súbeo como «Paquete SCORM». Amosará sempre a última versión da túa nube.",
  "Responder más tarde, sin presentar": "Responder máis tarde, sen presentar",
  "Abrirla para responder con un enlace, cuando cada uno quiera": "Abrila para responder cunha ligazón, cando cada un queira",
  "Para esto, guárdala en tu nube de Revela.": "Para isto, gárdaa na túa nube de Revela.",
  "Comparte el enlace: cada persona responde desde su móvil u ordenador. El enlace funciona en cuanto se guarde la presentación; trae las respuestas para verlas aquí y al presentar.": "Comparte a ligazón: cada persoa responde desde o móbil ou o ordenador. A ligazón funciona en canto se garde a presentación; trae as respostas para velas aquí e ao presentar.",
  "Traer las respuestas": "Traer as respostas",
  "{n} respuestas por enlace": "{n} respostas por ligazón",
  "No se pudieron traer.": "Non se puideron traer.",
  "Buscar en internet datos actuales y citar las fuentes (unos céntimos más)": "Buscar en internet datos actuais e citar as fontes (uns céntimos máis)",
  "Respuesta dibujada": "Resposta debuxada",
  "Respuesta con una foto": "Resposta cunha foto",
  "Cada persona dibuja con el dedo en su móvil (encima de la imagen, si eliges una) y los dibujos salen en un muro.": "Cada persoa debuxa co dedo no móbil (enriba da imaxe, se escolles unha) e os debuxos saen nun muro.",
  "Cada persona hace o elige una foto (su cuaderno, una maqueta, algo que ha encontrado) y salen en un muro.": "Cada persoa fai ou escolle unha foto (o caderno, unha maqueta, algo que atopou) e saen nun muro.",
  "Respuesta de voz (audio)": "Resposta de voz (audio)",
  "Cada persona graba con el móvil una respuesta de voz (hasta 30 segundos) y salen en un muro, las más recientes primero; haz clic en una para escucharla. Este navegador guarda las más recientes: unas diez de 30 segundos.": "Cada persoa grava co móbil unha resposta de voz (ata 30 segundos) e saen nun muro, as máis recentes primeiro; fai clic nunha para escoitala. Este navegador garda as máis recentes: unhas dez de 30 segundos.",
  "Carrera animada": "Carreira animada",
  "Carrera: cada jugador (o cada equipo) avanza hacia la meta, los puntos de todos los cuestionarios; al volver a la diapositiva, sale desde donde estaba. En un cuestionario, se ve al mostrar la respuesta.": "Carreira: cada xogador (ou cada equipo) avanza cara á meta, os puntos de todos os cuestionarios; ao volver á diapositiva, sae desde onde estaba. Nun cuestionario, vese ao amosar a resposta.",
  "Elegir a alguien al azar": "Escoller a alguén ao chou",
  "¿A quién le toca?": "A quen lle toca?",
  "Clic para cerrar · N para otra vez": "Clic para pechar · N para outra vez",
  "Aún no hay nadie con nombre: que lo escriban al entrar en la votación.": "Aínda non hai ninguén con nome: que o escriban ao entrar na votación.",
  "Modo": "Modo",
  "Rapidez: más puntos cuanto antes": "Rapidez: máis puntos canto antes",
  "Precisión: solo cuenta acertar, sin prisa": "Precisión: só conta acertar, sen présa",
  "Confianza: cada uno dice lo seguro que está": "Confianza: cada un di o seguro que está",
  "Por equipos (un nombre por línea; vacío: cada uno por su cuenta)": "Por equipos (un nome por liña; baleiro: cada un pola súa conta)",
  "Vale para todos los cuestionarios de la presentación: cada móvil elige equipo y la clasificación muestra la media de cada equipo. Al responder se ganan estrellas (una por respuesta y otra por acierto) y cada 5, un nivel.": "Vale para todos os cuestionarios da presentación: cada móbil escolle equipo e a clasificación amosa a media de cada equipo. Ao responder gáñanse estrelas (unha por resposta e outra por acerto) e cada 5, un nivel.",
  "Corregir con IA las respuestas": "Corrixir as respostas con IA",
  "Criterios para corregir con IA (opcional)": "Criterios para corrixir con IA (opcional)",
  "p. ej.: Nombra las tres partes, pon un ejemplo y usa los términos vistos.": "p. ex.: Nomea as tres partes, pon un exemplo e usa os termos vistos.",
  "También al presentar desde el editor: clic derecho ▸ «Corregir con IA las respuestas»; a cada móvil le llega su nota y un comentario.": "Tamén ao presentar desde o editor: clic dereito ▸ «Corrixir as respostas con IA»; a cada móbil chégalle a súa nota e un comentario.",
