  "Cada participante abre el enlace en su dispositivo, escribe su nombre y recorre la presentación a su ritmo respondiendo las actividades. Aquí ves en directo por dónde va cada uno y cómo le va.": "Cada participante abre a ligazón no seu dispositivo, escribe o seu nome e percorre a presentación ao seu ritmo respondendo ás actividades. Aquí ves en directo por onde vai cada un e como lle vai.",
