  "Al presentar, el vídeo se para en ese segundo y hace la pregunta; al responder se ve la correcta y sigue. Pon un asterisco (*) delante de la respuesta correcta; sin asterisco, es una pregunta para pensar.": "Ao presentar, o vídeo detense nese segundo e fai a pregunta; ao responder vese a correcta e segue. Pon un asterisco (*) diante da resposta correcta; sen asterisco, é unha pregunta para pensar.",
  "Añadir una pregunta en este momento": "Engadir unha pregunta neste momento",
  "Proponer preguntas con IA": "Propor preguntas con IA",
  "Ir a ese momento": "Ir a ese momento",
  "Una opción por línea; * delante de la correcta": "Unha opción por liña; * diante da correcta",
  "Explicación (opcional)": "Explicación (opcional)",
  "La IA no pudo proponer preguntas para este vídeo (si es de otra web, puede que no deje leerlo).": "A IA non puido propor preguntas para este vídeo (se é doutra web, pode que non deixe lelo).",
  "Desarrolladores e IA": "Desenvolvedores e IA",
  "Conecta Revela a Claude, ChatGPT u otra aplicación de IA para que cree y cambie tus presentaciones: añade un conector personalizado con esta dirección y acepta el permiso que te pedirá Revela.": "Conecta Revela a Claude, ChatGPT ou outra aplicación de IA para que cree e cambie as túas presentacións: engade un conector personalizado con este enderezo e acepta o permiso que che pedirá Revela.",
  "Para tus propios programas, crea una clave de API. Trátala como una contraseña: quien la tenga puede leer y cambiar tus presentaciones.": "Para os teus propios programas, crea unha chave de API. Trátaa como un contrasinal: quen a teña pode ler e cambiar as túas presentacións.",
  "Documentación": "Documentación",
  "Crear una clave de API": "Crear unha chave de API",
  "Conectada: {app}": "Conectada: {app}",
  "Creada: {d}": "Creada: {d}",
  "Último uso: {d}": "Último uso: {d}",
  "Sin usar todavía": "Aínda sen usar",
  "Ninguna aplicación conectada ni clave creada.": "Ningunha aplicación conectada nin chave creada.",
  "¿Quitarle el acceso? Lo que use esta clave o esta aplicación dejará de poder entrar en tus presentaciones.": "Quitarlle o acceso? O que use esta chave ou esta aplicación deixará de poder entrar nas túas presentacións.",
  "Un nombre para recordar para qué es (por ejemplo, «Script de informes»):": "Un nome para lembrar para que é (por exemplo, «Script de informes»):",
  "Tu clave de API. Cópiala ahora: no se volverá a mostrar.": "A túa chave de API. Cópiaa agora: non se volverá mostrar.",
