  "HTML": "HTML",
  "CSS y HTML": "CSS e HTML",
  "HTML de este objeto": "HTML deste obxecto",
  "Una página propia dentro de la diapositiva: HTML, CSS y JavaScript. Se ejecuta aislada: no puede tocar la presentación ni los datos de quien la ve.": "Unha páxina propia dentro da diapositiva: HTML, CSS e JavaScript. Execútase illada: non pode tocar a presentación nin os datos de quen a ve.",
  "Clases CSS de este objeto": "Clases CSS deste obxecto",
  "CSS de la presentación": "CSS da presentación",
  "Se aplica dentro de cada diapositiva, al editar, al presentar y al compartir. Pon clases a los objetos y úsalas aquí; «&» es la propia diapositiva.": "Aplícase dentro de cada diapositiva, ao editar, presentar e compartir. Pon clases aos obxectos e úsaas aquí; «&» é a propia diapositiva.",
  "El CSS es demasiado largo.": "O CSS é demasiado longo.",
  "El CSS tiene llaves sin cerrar o de más: revísalo.": "O CSS ten chaves sen pechar ou de máis: revísao.",
  "Un objeto con tu propio HTML, CSS y JavaScript, aislado del resto (modo desarrollador)": "Un obxecto co teu propio HTML, CSS e JavaScript, illado do resto (modo desenvolvedor)",
  "Modo desarrollador: el CSS propio de la presentación, las clases de cada objeto y el HTML de los objetos HTML": "Modo desenvolvedor: o CSS propio da presentación, as clases de cada obxecto e o HTML dos obxectos HTML",
  "Me gusta": "Gústame",
  "¡Gracias! Así otros docentes la encontrarán antes.": "Grazas! Así outros docentes atoparana antes.",
  "CSS y<br>HTML": "CSS e<br>HTML",
  "Comparte este enlace: quien lo abra verá la presentación en su navegador, siguiendo tus diapositivas y tu puntero, sin cuenta y sin instalar nada. Sirve para cientos o miles de personas.": "Comparte esta ligazón: quen a abra verá a presentación no seu navegador, seguindo as túas diapositivas e o teu punteiro, sen conta e sen instalar nada. Serve para centos ou miles de persoas.",
  "Emitir en directo": "Emitir en directo",
  "Emitir en<br>directo": "Emitir en<br>directo",
  "Empezar a presentar": "Comezar a presentar",
  "En directo": "En directo",
  "La emisión ha terminado": "A emisión rematou",
  "Para emitirla en directo, guárdala en tu nube de Revela (Archivo ▸ Mi nube): el público la abre desde allí.": "Para emitila en directo, gárdaa na túa nube de Revela (Arquivo ▸ A miña nube): o público ábrea desde alí.",
  "Para que el público la vea sin cuenta, cualquiera con el enlace podrá verla como presentación (sin el editor ni las notas). ¿Continuar?": "Para que o público a vexa sen conta, calquera coa ligazón poderá vela como presentación (sen o editor nin as notas). Continuar?",
  "Para que el público la vea sin cuenta, quien la comparte debe dejar que cualquiera con el enlace pueda presentarla.": "Para que o público a vexa sen conta, quen a comparte debe deixar que calquera coa ligazón poida presentala.",
  "Para un público grande: quien abra el enlace sigue tus diapositivas y tu puntero en su navegador, sin cuenta (cientos o miles de personas)": "Para un público grande: quen abra a ligazón segue as túas diapositivas e o teu punteiro no navegador, sen conta (centos ou miles de persoas)",
  "Solo quien puede editarla puede emitirla.": "Só quen pode editala pode emitila.",
