  "Antes de crear tu cuenta, acepta las condiciones y vuelve a intentarlo.": "Antes de crear a túa conta, acepta as condicións e téntao de novo.",
  "Añade este registro TXT en su DNS:": "Engade este rexistro TXT no seu DNS:",
  "Aún no se ve el registro TXT. Los cambios de DNS pueden tardar unos minutos.": "Aínda non se ve o rexistro TXT. Os cambios de DNS poden tardar uns minutos.",
  "Dominios de correo (separados por comas)": "Dominios de correo (separados por comas)",
