  "Ese dominio ya lo usa otro equipo de Revela. Escríbenos si es tuyo.": "Outro equipo de Revela xa usa ese dominio. Escríbenos se é teu.",
  "Ese es un dominio de correo público: solo los dominios de tu centro o empresa.": "Ese é un dominio de correo público: só os dominios do teu centro ou empresa.",
  "Id. de cliente": "Id. de cliente",
  "Inicio de sesión único (SSO)": "Inicio de sesión único (SSO)",
  "No se ha podido iniciar sesión con tu proveedor de identidad. Vuelve a intentarlo o avisa a quien administra vuestro equipo.": "Non se puido iniciar sesión co teu provedor de identidade. Téntao de novo ou avisa a quen administra o equipo.",
  "Quien entre así se une al equipo (si quedan puestos)": "Quen entre así únese ao equipo (se quedan postos)",
