  "Secreto de cliente": "Segredo de cliente",
  "Si tu centro o empresa entra con su propio proveedor (Microsoft, Okta…)": "Se o teu centro ou empresa entra co seu propio provedor (Microsoft, Okta…)",
  "Tu centro o empresa no tiene configurado el inicio de sesión único en Revela. Entra con Google o pide a quien administra vuestro equipo que lo configure.": "O teu centro ou empresa non ten configurado o inicio de sesión único en Revela. Entra con Google ou pide a quen administra o equipo que o configure.",
  "Tu correo del centro o de la empresa:": "O teu correo do centro ou da empresa:",
  "Tu equipo entra con su propio proveedor de identidad (Microsoft Entra ID, Okta, Google Workspace u otro compatible con OpenID Connect). Regístralo allí con esta dirección de vuelta:": "O teu equipo entra co seu propio provedor de identidade (Microsoft Entra ID, Okta, Google Workspace ou outro compatible con OpenID Connect). Rexistra alí Revela con este enderezo de volta:",
  "Tu proveedor de identidad devolvió un correo que no es de los dominios de tu equipo.": "O teu provedor de identidade devolveu un correo que non é dos dominios do teu equipo.",
  "verificado": "verificado",
  "Avisos en Slack, Microsoft Teams, Google Chat, Discord o cualquier dirección (Zapier, Make…): cuando alguien abra uno de tus enlaces con seguimiento o comente tus presentaciones.": "Avisos en Slack, Microsoft Teams, Google Chat, Discord ou calquera enderezo (Zapier, Make…): cando alguén abra unha das túas ligazóns con seguimento ou comente as túas presentacións.",
  "Añadir un canal de avisos": "Engadir unha canle de avisos",
  "Cada aviso llega como JSON firmado: comprueba la cabecera X-Revela-Signature (sha256 HMAC del cuerpo) con este secreto. Cópialo ahora: no se volverá a mostrar.": "Cada aviso chega como JSON asinado: comproba a cabeceira X-Revela-Signature (HMAC sha256 do corpo) con este segredo. Cópiao agora: non se volverá mostrar.",
