  "De mi equipo": "O meu equipo",
  "Los logotipos e imágenes de tu equipo: lo que sube cualquier miembro lo pueden usar todos.": "Os logotipos e imaxes do teu equipo: o que sobe calquera membro pódeno usar todos.",
  "Subir una imagen al equipo": "Subir unha imaxe ao equipo",
  "Subida: ya la puede usar todo el equipo": "Subida: xa a pode usar todo o equipo",
  "El espacio de imágenes del equipo está lleno.": "O espazo de imaxes do equipo está cheo.",
