  "Actividad: crucigrama": "Actividade: encrucillado",
  "Actividad: sopa de letras": "Actividade: sopa de letras",
  "Actividad: memoria (parejas)": "Actividade: memoria (parellas)",
  "Una palabra por línea con su pista: «PALABRA = pista». Revela monta el crucigrama; en los móviles salen la cuadrícula y las pistas numeradas, nunca las palabras. Da igual mayúsculas, tildes y espacios.": "Unha palabra por liña coa súa pista: «PALABRA = pista». Revela monta o encrucillado; nos móbiles saen a grade e as pistas numeradas, nunca as palabras. Dá igual maiúsculas, tiles e espazos.",
  "Las palabras que hay que encontrar, una por línea; con «PALABRA = pista», en los móviles sale la pista en lugar de la palabra. Revela las esconde en horizontal, en vertical y en diagonal, y rellena el resto con letras de las mismas palabras.": "As palabras que hai que atopar, unha por liña; con «PALABRA = pista», nos móbiles sae a pista en lugar da palabra. Revela agóchaas en horizontal, en vertical e en diagonal, e enche o resto con letras das mesmas palabras.",
  "Una pareja por línea: «A = B». En los móviles salen las cartas boca abajo y cada persona busca las parejas; cuentan las parejas encontradas y, para desempatar, los intentos. Es para practicar: el móvil necesita las dos caras de cada carta para jugar.": "Unha parella por liña: «A = B». Nos móbiles saen as cartas boca abaixo e cada persoa busca as parellas; contan as parellas atopadas e, para desempatar, os intentos. É para practicar: o móbil necesita as dúas caras de cada carta para xogar.",
