  "Importar preguntas": "Importar preguntas",
  "Cada pregunta, en una diapositiva nueva con su votación (cuestionario, unir parejas, completar huecos o número), detrás de la diapositiva actual.": "Cada pregunta, nunha diapositiva nova coa súa votación (cuestionario, unir parellas, completar ocos ou número), detrás da diapositiva actual.",
  "opción múltiple, verdadero/falso, emparejamiento, respuesta corta, numérica y huecos (cloze) de respuesta corta.": "opción múltiple, verdadeiro/falso, emparellamento, resposta curta, numérica e ocos (cloze) de resposta curta.",
  "el formato de texto de Moodle: =correcta ~incorrecta, {T}/{F}, parejas con ->, respuesta corta y numérica con #.": "o formato de texto de Moodle: =correcta ~incorrecta, {T}/{F}, parellas con ->, resposta curta e numérica con #.",
  "su plantilla de hoja de cálculo (pregunta, respuestas 1 a 4, tiempo y respuestas correctas).": "o seu modelo de folla de cálculo (pregunta, respostas 1 a 4, tempo e respostas correctas).",
  "una pregunta por fila: pregunta, respuesta correcta, incorrecta 1, incorrecta 2, incorrecta 3. Separado por comas o punto y coma; la primera fila puede ser de títulos. Solo con la correcta, es de respuesta corta (varias válidas separadas por |).": "unha pregunta por fila: pregunta, resposta correcta, incorrecta 1, incorrecta 2, incorrecta 3. Separado por comas ou punto e coma; a primeira fila pode ser de títulos. Só coa correcta, é de resposta curta (varias válidas separadas por |).",
