  "Exportar preguntas": "Exportar preguntas",
  "Los cuestionarios y actividades de la presentación ({n}), para un banco de preguntas de Moodle, Kahoot u otra herramienta.": "Os cuestionarios e actividades da presentación ({n}), para un banco de preguntas de Moodle, Kahoot ou outra ferramenta.",
  "{n} preguntas en este formato.": "{n} preguntas neste formato.",
  "Preguntas exportadas: {n}.": "Preguntas exportadas: {n}.",
  "Una página web para estudiar por tu cuenta, también sin internet y en el móvil: fichas para darles la vuelta (recuerda cuáles sabes) y práctica de los cuestionarios y actividades, con la respuesta al momento y la nota al final.": "Unha páxina web para estudar pola túa conta, tamén sen internet e no móbil: fichas para darlles a volta (lembra cales sabes) e práctica dos cuestionarios e actividades, coa resposta ao momento e a nota ao final.",
  "Practicar las preguntas": "Practicar as preguntas",
  "Una ficha más por diapositiva: su título delante y su texto detrás": "Unha ficha máis por diapositiva: o seu título diante e o seu texto detrás",
  "{c} fichas y {p} preguntas para practicar.": "{c} fichas e {p} preguntas para practicar.",
  "Añade cuestionarios o actividades (Insertar ▸ Votación en directo) o marca las diapositivas.": "Engade cuestionarios ou actividades (Inserir ▸ Votación en directo) ou marca as diapositivas.",
  "Página de estudio descargada: se abre con cualquier navegador, también sin conexión.": "Páxina de estudo descargada: ábrese con calquera navegador, tamén sen conexión.",
