  "Actividad: rueda de letras": "Actividade: roda de letras",
  "Rueda de letras": "Roda de letras",
  "Una letra por línea: «A = respuesta = pista» (sin la letra, vale la primera de la respuesta; «~» delante para «Contiene la…» en lugar de «Empieza por la…»; «a|b» si valen dos respuestas). En los móviles salen la rueda, la letra y la pista, nunca la respuesta. Al presentar, la tecla J la juega en la pantalla con una sola persona, sin móviles.": "Unha letra por liña: «A = resposta = pista» (sen a letra, vale a primeira da resposta; «~» diante para «Contén a…» en lugar de «Comeza pola…»; «a|b» se valen dúas respostas). Nos móbiles saen a roda, a letra e a pista, nunca a resposta. Ao presentar, a tecla J xógaa na pantalla cunha soa persoa, sen móbiles.",
